var g = SugarCube.State.variables;
var before = document.querySelectorAll('.npc-panel-item').length;
// satisfy the show_when gate + give Sal some arousal
if(!g.flags) g.flags = {};
g.flags.sal_opened_up = true;
var uuid = (setup.npc_slug_map && setup.npc_slug_map['npc_sal']);
if (g.npcs && uuid && g.npcs[uuid]) { g.npcs[uuid].core_traits.arousal = 2; }
SugarCube.Engine.show();   // re-render caption/sidebar
var cards = document.querySelectorAll('.npc-panel-item');
var out = '';
if (cards.length) { out = cards[0].textContent.replace(/\s+/g,' ').trim(); }
return JSON.stringify({ before_cards: before, uuid: uuid, after_cards: cards.length, card_text: out });

